-- public.pick_monster(p_world uuid, p_x integer, p_y integer)
-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION public.pick_monster(p_world uuid, p_x integer, p_y integer)
 RETURNS text
 LANGUAGE plpgsql
 STABLE
AS $function$
declare got text; want double precision; v_r int; v_k int;
begin
  v_r := region_at(p_world, p_x + 0.5, p_y + 0.5);
  v_k := coalesce(region_monsters(v_r), 0);
  -- Monster country keeps its own count, that many times the cap; the rest of
  -- the chart shares the cap among what stands outside it.
  -- And one kept to an island only on that island (`monster_isle`).
  select w.species into got from wild_table w
  where w.monster and (monster_isle(w.species) is null or monster_isle(w.species) = v_r) and (select count(*) from creature c
    where c.world_id = p_world and c.mode = 'wild' and c.species = w.species
      and case when v_k > 0 then region_at(p_world, c.to_x, c.to_y) is not distinct from v_r
               else coalesce(region_monsters(region_at(p_world, c.to_x, c.to_y)), 0) = 0 end
    ) < w.cap * greatest(v_k, 1)
  order by random() / greatest(1e-9, w.weight) limit 1;
  if got is null then return null; end if;
  want := case got when 'dragon' then 90 when 'ogre' then 55 when 'orc' then 40 else 26 end;
  if exists (select 1 from deed dd where dd.world_id = p_world
             and sqrt((p_x - dd.x) ^ 2 + (p_y - dd.y) ^ 2) < want) then
    return null;
  end if;
  return got;
end $function$
